import{_ as o,o as c,c as t,a2 as d}from"./chunks/framework.BM5YPQmL.js";const h=JSON.parse('{"title":"网卡与无线驱动","description":"","frontmatter":{},"headers":[],"relativePath":"zh/l1/driver-nic.md","filePath":"zh/l1/driver-nic.md"}'),a={name:"zh/l1/driver-nic.md"};function r(i,e,s,l,n,_){return c(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="网卡与无线驱动" tabindex="-1">网卡与无线驱动 <a class="header-anchor" href="#网卡与无线驱动" aria-label="Permalink to &quot;网卡与无线驱动&quot;">​</a></h1><p>一个网络家族如何加入 net 服务。</p><h2 id="模型-3-0-0" tabindex="-1">模型（3.0.0） <a class="header-anchor" href="#模型-3-0-0" aria-label="Permalink to &quot;模型（3.0.0）&quot;">​</a></h2><ul><li>驱动住在 <code>ocos/drivers/net/</code> - 每个家族一个文件 （<code>drv_net_e1000e.c</code>、<code>drv_net_igb.c</code>、<code>drv_net_ixgbe.c</code>、 <code>drv_net_rtl8139.c</code>、<code>drv_net_rtl8169.c</code>、<code>drv_net_bcm57xx.c</code>、 <code>drv_net_other.c</code>），外加无线栈 （<code>drv_net_wireless.c</code>、<code>drv_net_ath.c</code>、<code>drv_net_brcm.c</code>、 <code>drv_net_iwlwifi.c</code>、<code>drv_net_rtlwifi.c</code>）。</li><li>身份：<code>OC_DRIVER_DECL(&quot;nic&quot;, &quot;e1000e&quot;, &amp;ops, &quot;Intel e1000e&quot;)</code><ul><li>802.11 家族则用 <code>&quot;wireless&quot;</code> 类。启动收集器探测；家族自报 诚实状态（registered / scanning / connected）。</li></ul></li><li>驱动内部表 API 是 <code>drv_net_api.h</code> - 内核内部，只从家族自己的 探测路径修改。</li><li>net 服务（<code>ocos/services/net/</code>）拥有协议栈：IPv4 + TCP/UDP、 DHCP、DNS、防火墙/netfilter、TLS、SSH/sshd，以及 L1SVC 类别 3/8 表面。</li></ul><h2 id="无线层" tabindex="-1">无线层 <a class="header-anchor" href="#无线层" aria-label="Permalink to &quot;无线层&quot;">​</a></h2><p><code>wifi</code>（status / scan / test / sdio）报告每家族状态与来自 beacon 的扫描列表；<code>bt</code>（status / usb / uart / test）代理蓝牙 传输（<code>drv_misc_bt_usb.c</code> 里的 HCI-USB、H4 UART、完整的 L2CAP/SDP/RFCOMM/SPP 链）。没有硬件 -&gt; 诚实的 &quot;no wireless devices registered&quot; 行，绝不是假列表。</p><h2 id="一个新家族长什么样" tabindex="-1">一个新家族长什么样 <a class="header-anchor" href="#一个新家族长什么样" aria-label="Permalink to &quot;一个新家族长什么样&quot;">​</a></h2><ol><li><code>ocos/drivers/net/drv_net_&lt;fam&gt;.{c,h}</code> - PCI 探测、MAC 设置、 把 RX/TX 接入服务的包路径。</li><li><code>OC_DRIVER_DECL(&quot;nic&quot;, &quot;&lt;fam&gt;&quot;, &amp;ops, &quot;description&quot;)</code>。</li><li>可选的状态/测试操作：在 <code>svc_sysapi_l1svc.h</code> 追加编号、重新 生成镜像、加经典表行（<code>net-tool</code> 的 <code>g_ops[]</code>）或一个薄包装 文件夹。</li></ol><h2 id="消费者契约" tabindex="-1">消费者契约 <a class="header-anchor" href="#消费者契约" aria-label="Permalink to &quot;消费者契约&quot;">​</a></h2><p>应用调用服务，从不调用驱动：<code>net-tool ip</code> -&gt; <code>sys_l1svc(NET, IP, ...)</code>；<code>ping</code>/<code>wget</code> 走 <code>SYS_NETCMD</code> 桥 （op 2 / 4）。输出行（<code>&quot;IP: ...&quot;</code>、<code>&quot;DHCP success: IP=...&quot;</code>、 <code>&quot;DNS resolution failed (timeout)&quot;</code>）是更新向导和文档依赖的 锚点 - 见 <a href="./surface-map.html">surface-map.md</a>。</p>',10)])])}const q=o(a,[["render",r]]);export{h as __pageData,q as default};
